var $jscomp = $jscomp || {};
$jscomp.scope = {};
$jscomp.arrayIteratorImpl = function (a) {
  var b = 0;
  return function () {
    return b < a.length ? { done: !1, value: a[b++] } : { done: !0 };
  };
};
$jscomp.arrayIterator = function (a) {
  return { next: $jscomp.arrayIteratorImpl(a) };
};
$jscomp.makeIterator = function (a) {
  var b = typeof Symbol != "undefined" && Symbol.iterator && a[Symbol.iterator];
  return b ? b.call(a) : $jscomp.arrayIterator(a);
};

var arabicDays = "الاحد الاثنين الثلاثاء الاربعاء الخميس الجمعة السبت".split(" ");
var arabicMonths =
  "يناير فبراير مارس ابريل ماي يونيو يوليو اغسطس سبتمبر اكتوبر نوفمبر ديسمبر".split(
    " "
  );
var hijriMonths =
  "محرم;صفر;ربيع الأول;ربيع الثانى;جمادى الأولى;جمادى الثانية;رجب;شعبان;رمضان;شوال;ذو القعدة;ذو الحجة".split(
    ";"
  );

function fitText(el, kompressor) {
  if (!el || !el.clientWidth) return el;
  var textLen = el.innerText ? el.innerText.length : 1;
  el.style.fontSize =
    Math.ceil((10 * el.clientWidth * (kompressor || 1)) / textLen) + "px";
  return el;
}

function loadAdvImage(container) {
  if (!container) return;
  var imgPath = container.getAttribute("hot-img-path") || "1.jpg";
  container.style.textAlign = "center";
  var img = new Image();
  img.src = "adimg/" + imgPath;
  img.classList.add("adv-img");
  if (img.complete) {
    container.innerHTML = img.outerHTML;
  } else {
    img.onload = function () {
      container.innerHTML = img.outerHTML;
    };
    img.onerror = function () {
      var logo = document.querySelector(".logo");
      if (logo) logo.style.paddingTop = "50px";
      var section = document.querySelector(".section");
      if (section && section.hasAttribute("enable-hot-marquee")) {
        section.style.display = "block";
      }
    };
  }
}

function startClock(el) {
  if (!el) return;
  el.innerHTML = getFormattedTime();
  setInterval(function () {
    el.innerHTML = getFormattedTime();
  }, 1000);
}

function getFormattedTime() {
  var now = new Date();
  var sec = ("0" + now.getSeconds()).slice(-2);
  var min = ("0" + now.getMinutes()).slice(-2);
  var hours = now.getHours();
  var ampm = hours >= 12 ? "مساءً" : "صباحاً";
  hours = hours % 12;
  hours = hours ? hours : 12;
  var hourStr = ("0" + hours).slice(-2);
  return "الساعة الآن " + hourStr + ":" + min + ":" + sec + " " + ampm;
}

function startFitText() {
  try {
    var elements = document.querySelectorAll("[data-fit-text]");
    if (!elements || !elements.length) return;
    elements.forEach(function (el) {
      fitText(el, 0.215);
    });
  } catch (err) {
    console.debug("startFitText:", err);
  }
}

document.addEventListener("DOMContentLoaded", function () {
  // Gregorian Date
  var dateEl = document.querySelector("[hot-date]");
  if (dateEl) {
    var now = new Date();
    dateEl.innerHTML =
      arabicDays[now.getDay()] +
      " " +
      now.getDate() +
      " " +
      arabicMonths[now.getMonth()] +
      " " +
      now.getFullYear();
  }

  // Time Clock
  var timeEl = document.querySelector("[hot-time]");
  if (timeEl) {
    startClock(timeEl);
  }

  // Adv Image
  var advImgEl = document.querySelector("div[hot-adv-img]");
  if (advImgEl) {
    loadAdvImage(advImgEl);
  }

  // Hijri Date Calculation
  var hijriEl = document.querySelector("[hot-hijri-date]");
  if (hijriEl) {
    var adjustDays = parseInt(hijriEl.getAttribute("hot-adjust-days") || "0");
    var withDay = hijriEl.getAttribute("hot-with-day") !== null;
    var d = new Date();
    if (adjustDays) d.setDate(d.getDate() + adjustDays);

    var day = d.getDate();
    var month = d.getMonth() + 1;
    var year = d.getFullYear();

    if (month < 3) {
      year -= 1;
      month += 12;
    }

    var a = Math.floor(year / 100);
    var b = 2 - a + Math.floor(a / 4);
    if (year < 1583) b = 0;
    if (year === 1582) {
      if (month > 10) b = -10;
      if (month === 10) {
        b = 0;
        if (day > 4) b = -10;
      }
    }

    var jd =
      Math.floor(365.25 * (year + 4716)) +
      Math.floor(30.6001 * (month + 1)) +
      day +
      b -
      1524;
    b = 0;
    if (jd > 2299160) {
      a = Math.floor((jd - 1867216.25) / 36524.25);
      b = 1 + a - Math.floor(a / 4);
    }

    var l = jd - 1948084;
    var n = Math.floor(l / 10631);
    l = l - 10631 * n;
    var j = Math.floor((l - 0.1335) / (10631 / 30));
    l = l - Math.floor(j * (10631 / 30) + 0.1335);
    var k = Math.floor((l + 28.5001) / 29.5);
    if (k === 13) k = 12;
    var hDay = l - Math.floor(29.5001 * k - 29);
    var hMonth = k - 1;
    var hYear = 30 * n + j;

    var hijriStr =
      hDay +
      " " +
      (hijriMonths[hMonth] || "") +
      " " +
      hYear +
      " هـ";
    if (withDay) {
      hijriStr = arabicDays[d.getDay()] + "، " + hijriStr;
    }
    hijriEl.innerText = hijriStr;
  }
});
